import base64
import fcntl
import shutil
import tempfile
import time
from contextlib import contextmanager


@contextmanager
def install_lock():
    fd = os.open('/usr/local/lib', os.O_RDONLY | os.O_DIRECTORY)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        yield
    finally:
        os.close(fd)


def install_runner(request):
